-- -----------------------------------
-- Table structure for `testingcount`
-- -----------------------------------

DROP TABLE IF EXISTS `testingcount`;
CREATE TABLE `testingcount` (
  `Test_Id` int(11) NOT NULL AUTO_INCREMENT,
  `Atmid` varchar(250) CHARACTER SET utf8 NOT NULL,
  `name` varchar(250) CHARACTER SET utf8 NOT NULL,
  `entrydate` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Action` varchar(250) CHARACTER SET utf8 NOT NULL,
  `engiName` varchar(100) CHARACTER SET utf8 NOT NULL,
  PRIMARY KEY (`Test_Id`)
) ENGINE=MyISAM AUTO_INCREMENT=15302 DEFAULT CHARSET=latin1;

